// Guided conversation standard: one question, one useful explanation, one next action.
const simpleDiscovery={title:'let’s understand your business',intro:'a few questions to understand where you are and what you want to build.',qs:[Q('business','what is your business called?'),Q('stage','which stage best describes you?','select',["i have an idea but haven’t started",'i am just starting','i already have clients or customers','i have a business and want to expand']),Q('vision','what do you want this business to become?','textarea'),Q('goal','what is your main goal right now?','select',['attract more customers and win better projects','build a professional brand and reputation','organize operations, staff and finances','win corporate or larger contracts','expand and grow the business','help me understand what to do first']),Q('challenge','what is holding you back the most?','select',["i don’t have a clear plan or structure",'getting consistent customers','pricing, costs or cash flow','managing projects and delivering consistently','a team and better systems','something else or several things']),Q('assets','what do you already have?','multiselect',['business registration','logo and branding','social media pages','work portfolio or past projects','staff or contractors','business processes and records','website','none yet']),Q('pace','how would you prefer to build your business?','select',['start with a few affordable priorities','build in stages as i can afford them','review a complete package','recommend priorities first; i’ll decide after reviewing the cost'])]};
if(!db.simpleConversationV1){let f=db.forms.find(f=>f.id==='general');Object.assign(f,structuredClone(simpleDiscovery));f.published={...structuredClone(simpleDiscovery),at:now()};db.simpleConversationV1=true;save()}
let conversationStep=0,conversationKey='',conversationAnswers={};
function questionInsight(q,answers){if(q.id==='stage')return ['your stage changes the route.','an idea may need validation and a starting plan. an operating business may need better positioning, delivery or systems.'];if(q.id==='vision')return ['you do not need a perfect business plan.','describe the future in your own words. we use that direction to keep the recommendations relevant.'];if(q.id==='assets')return ['we start with what you already have.','existing assets are checked before more work is proposed. select all that apply, or choose none yet.'];if(q.id==='pace')return ['you choose the pace.','your answer helps us organize the options. you will see the scope and cost before deciding what to buy.'];if(q.id==='challenge')return ['a symptom can have more than one cause.','tell us what feels hardest. the team will check the situation before deciding what needs to change.'];if(q.id==='goal')return ['choose the result that matters first.','we use your priority to recommend a practical starting point, rather than every available service.'];return q.id==='business'?['a working name is enough.','if the name is still being decided, say so. you can still explore the next step.']:['there is no perfect answer.','tell us what is true today. the team will use your answer to clarify a relevant next step.']}
discoveryView=function(){let f=db.forms.find(f=>f.id===route[1]);if(!f)return notFound();let id=(route[2]||'new').split('?')[0],l=lead(id),pub=l?.discoverySnapshot||f.published||f,key=f.id+'/'+id;if(conversationKey!==key){conversationKey=key;conversationStep=0;conversationAnswers={...(l?.answers||{}),...JSON.parse(localStorage.getItem('hh-conversation-'+key)||'{}')}}let contactStep=!l&&conversationStep===pub.qs.length,q=contactStep?Q('_contact','where can the team reach you?'):pub.qs[conversationStep];if(!q)return notFound();let value=conversationAnswers[q.id]||'',help=contactStep?['your next step stays connected.','use a sample email or whatsapp reference here. the live system will verify access before showing private work.']:questionInsight(q,conversationAnswers),count=pub.qs.length+(l?0:1);return `<div class="guidedwrap"><header class="guidednav"><a href="#home"><img class="logo" src="assets/${brandFor()?brandFor().name==='hamzury hub'?'hub':brandFor().name:'hamzury'}.png" alt="hamzury"></a><a href="https://desk.hamzury.com" target="_blank" rel="noopener">need a hand?</a></header><div class="guidedprogress"><span>${contactStep?'your return reference':E(pub.title)}</span><span>${contactStep?'contact details':`${conversationStep+1} / ${pub.qs.length}`}</span></div><div class="progress">${Array.from({length:count},(_,i)=>`<i class="${i<=conversationStep?'done':''}"></i>`).join('')}</div><div class="guidedcontent"><div class="eyebrow">awareness / understand before investing</div><form onsubmit="saveConversationAnswer(event,'${f.id}','${id}')"><h1>${E(q.label)}</h1><p class="questionhint">${help[0]}</p>${q.type==='select'||q.type==='multiselect'?`<fieldset class="answerchoices"><legend class="sr-only">${E(q.label)}</legend>${q.options.map((o,i)=>{let checked=Array.isArray(value)?value.includes(o):value===o;return `<label class="answeroption ${checked?'chosen':''}"><input type="${q.type==='multiselect'?'checkbox':'radio'}" name="answer" value="${E(o)}" ${checked?'checked':''} ${q.type==='select'?'required':''} onchange="updateConversationChoice(this,${q.type==='multiselect'})"><span>${E(o)}</span><b aria-hidden="true">${String(i+1).padStart(2,'0')}</b></label>`}).join('')}</fieldset>`:`<label class="sr-only" for="conversation-answer">your answer</label>${q.type==='textarea'?`<textarea id="conversation-answer" name="answer" required placeholder="tell us in your own words…">${E(value)}</textarea>`:`<input id="conversation-answer" name="answer" value="${E(value)}" required placeholder="${contactStep?'sample email or whatsapp reference':'a short answer is enough'}">`}`}<div class="guidedwhy"><span>why we ask</span><p>${help[1]}</p></div><div class="actions"><button>${contactStep||l&&conversationStep===pub.qs.length-1?'save & receive my reference →':'continue →'}</button>${conversationStep?'<button class="ghost" type="button" onclick="conversationStep--;render()">back</button>':''}</div><p class="small">no identity documents or payment are requested during discovery. demonstration answers stay in this browser.</p></form></div></div>`}
function updateConversationChoice(input,multi){let group=input.closest('fieldset');if(multi){if(input.value==='none yet'&&input.checked)group.querySelectorAll('input').forEach(el=>{if(el!==input)el.checked=false});else if(input.checked)group.querySelector('input[value="none yet"]')?.removeAttribute('checked');if(input.value!=='none yet'&&input.checked){let none=group.querySelector('input[value="none yet"]');if(none)none.checked=false}}group.querySelectorAll('label').forEach(label=>label.classList.toggle('chosen',label.querySelector('input').checked))}
function saveConversationAnswer(e,fid,id){e.preventDefault();let f=db.forms.find(f=>f.id===fid),existing=lead(id),pub=existing?.discoverySnapshot||f.published||f,contactStep=!existing&&conversationStep===pub.qs.length,q=contactStep?Q('_contact','contact'):pub.qs[conversationStep],d=new FormData(e.target),values=d.getAll('answer');if(q.type==='multiselect'&&!values.length){toast('choose the assets you have, or none yet');return}conversationAnswers[q.id]=q.type==='multiselect'?values:d.get('answer');localStorage.setItem('hh-conversation-'+conversationKey,JSON.stringify(conversationAnswers));if(conversationStep<pub.qs.length-1||!existing&&!contactStep){conversationStep++;render();window.scrollTo(0,0);return}let l=existing||db.leads.find(l=>conversationAnswers._contact&&l.contact?.trim().toLowerCase()===conversationAnswers._contact.trim().toLowerCase());if(!l){let src=new URLSearchParams(location.hash.split('?')[1]||'').get('source')||'holding website';l={id:uid('HH'),name:conversationAnswers.business||conversationAnswers[pub.qs[0].id]||'new enquiry',contact:conversationAnswers._contact,source:src,venture:db.ventures.find(v=>src===v.name+' website')?.name||'holding',scenario:fid,created:now(),proposal:'',proposalVersion:null,roadmapVersion:null,selected:[],paid:false,requirements:[],work:[],files:[],updates:[],events:[]};db.leads.unshift(l)}l.answers=structuredClone(conversationAnswers);l.stage='discovery';l.next='specialist team reviews the discovery and prepares a recommendation';event(l,'guided discovery received');flowGo(l,'reference')}
let requirementStep=0,requirementClient='';
function prepareRequirementJourney(l){if(l.atomicRequirements&&l.requirements.every(r=>r.kind&&r.why))return;l.requirementsArchive=structuredClone(l.requirements||[]);let vs=[...new Set(l.work.map(w=>w.venture))],requests=[{key:'business-name',title:'please confirm your business name.',kind:'text',why:'we use the correct name across your selected work. it can be confirmed here instead of asking every venture again.',venture:'holding',answer:l.answers.business||l.name,status:'needed'}];if(vs.includes('bizdoc')){requests.push({key:'existing-docs',title:'do you have existing business documents?',kind:'file',why:'existing documents help the team check what is already in place and avoid repeating work.',venture:'bizdoc',status:'needed'});if(l.requestIdentity||l.work.some(w=>w.venture==='bizdoc'&&/company registration/i.test(w.title)))requests.push({key:'nin-slip',title:'can you provide the requested nin slip?',kind:'file',sensitive:true,why:'this sample registration route includes an identity-evidence request for team review. actual identity files belong in the secure live portal. the team confirms the applicable requirements before processing.',venture:'bizdoc',status:'needed'});if(l.requestSignature||l.work.some(w=>w.venture==='bizdoc'&&/company registration|board resolution/i.test(w.title)))requests.push({key:'signature',title:'can you provide the requested signature?',kind:'file',sensitive:true,why:'a signature is requested only for the agreed document or application that needs it. the team confirms where it will be used.',venture:'bizdoc',status:'needed'})}if(vs.includes('medialy')||vs.includes('subt'))requests.push({key:'logo',title:'do you already have a logo?',kind:'file',why:'we can review and use an existing suitable logo. if you do not have one, tell us so the team can confirm the right next step.',venture:vs.includes('medialy')?'medialy':'subt',status:'needed'},{key:'existing-assets',title:'are there other files you want us to use?',kind:'file',why:'a profile, photographs, portfolio or existing content may help your team prepare the selected work. only share material you have permission to use.',venture:vs.includes('medialy')?'medialy':'subt',status:'needed'});l.requirements=requests.map(r=>({...r,id:uid('req'),answer:r.answer||'',due:'',fileIds:[]}));l.atomicRequirements=true;save()}
function requirementsConversation(l){prepareRequirementJourney(l);if(requirementClient!==l.id){requirementClient=l.id;let next=l.requirements.findIndex(r=>!['submitted','accepted','not available','later'].includes(r.status));requirementStep=next===-1?l.requirements.length:next}let completed=requirementStep>=l.requirements.length,r=l.requirements[requirementStep];if(completed)return flowHeader(l,'requirements')+flowTitle('systems / requirements received','thank you. we know what is ready.','your team can now check the information, identify any gaps and confirm the next action.')+`<div class="flow-message">${l.requirements.map((r,i)=>`<div class="row"><div><span class="small">${i+1}. ${E(r.title)}</span><p class="small">${E(r.status)}${r.fileIds?.length?' · sample file attached':''}</p></div><button class="secondary mini" onclick="requirementStep=${i};render()">change</button></div>`).join('')}</div><div class="flow-actions">${button('follow my project →','client/'+l.id+'/progress')}</div>`+flowEnd(l);return flowHeader(l,'requirements')+`<div class="requirement-counter"><span>one thing at a time</span><b>${requirementStep+1} / ${l.requirements.length}</b></div><div class="progress">${l.requirements.map((_,i)=>`<i class="${i<=requirementStep?'done':''}"></i>`).join('')}</div><section class="requirement-question"><div class="eyebrow">${E(r.venture)} / ${r.sensitive?'protected information':'your requirements'}</div><h1>${E(r.title)}</h1><p class="requirement-education">${E(r.why)}</p><form onsubmit="submitRequirementQuestion(event,'${l.id}','${r.id}')">${r.kind==='text'?`<label for="requirement-answer">your answer</label><input id="requirement-answer" name="answer" value="${E(r.answer)}" required><div class="flow-actions"><button>confirm & continue →</button></div>`:`<div class="requirement-options"><label class="answeroption ${r.status==='submitted'?'chosen':''}"><input type="radio" name="availability" value="provide" required ${r.status==='submitted'?'checked':''} onchange="showRequirementUpload(this)"><span>i can provide it</span></label><label class="answeroption ${r.status==='not available'?'chosen':''}"><input type="radio" name="availability" value="missing" ${r.status==='not available'?'checked':''} onchange="showRequirementUpload(this)"><span>i don’t have this</span></label><label class="answeroption ${r.status==='later'?'chosen':''}"><input type="radio" name="availability" value="later" ${r.status==='later'?'checked':''} onchange="showRequirementUpload(this)"><span>i’ll provide it later</span></label></div><div class="requirement-upload" ${r.status!=='submitted'?'hidden':''}>${r.sensitive?`<div class="flow-note">please do not upload an actual identity document or signature in this demo. choose the sample below. live submission requires the secure client portal.</div><label class="checkrow"><input type="checkbox" name="sampleSensitive" ${r.fileIds?.length?'checked':''}> use a sample ${r.key==='signature'?'signature':'identity file'} for this preview</label>`:`<label>choose a sample file, optional if already supplied</label><input type="file" name="supporting"><p class="small">use test files only, up to 2 mb. ${r.fileIds?.length?'a sample file is already attached.':''}</p>`}</div><label>anything the team should know? (optional)</label><textarea name="answer" placeholder="for example, a file is with your colleague or the logo is still being prepared">${E(r.answer)}</textarea><div class="flow-actions"><button>save & continue →</button></div>`}${requirementStep?'<button type="button" class="ghost small" onclick="requirementStep--;render()">back</button>':''}</form><div class="guidedwhy"><span>you stay in control</span><p>if something is missing, say so. your team will explain whether it affects the selected work or its delivery date.</p></div></section>`+flowEnd(l)}
function showRequirementUpload(input){let form=input.closest('form');form.querySelector('.requirement-upload').hidden=input.value!=='provide';form.querySelectorAll('.requirement-options label').forEach(label=>label.classList.toggle('chosen',label.querySelector('input').checked))}
async function submitRequirementQuestion(e,id,rid){e.preventDefault();let l=lead(id),r=l.requirements.find(r=>r.id===rid),d=new FormData(e.target),availability=d.get('availability');r.answer=d.get('answer')||'';if(r.kind==='file'&&availability==='provide'){let file=d.get('supporting');if(r.sensitive&&!d.get('sampleSensitive')){toast('use the sample-file option for this protected field');return}if(r.sensitive)file=new File(['hamzury demonstration placeholder. this is not a real identity document or signature.'],r.key+'-sample.txt',{type:'text/plain'});if(file?.size){if(file.size>2*1024*1024){toast('choose a sample file smaller than 2 mb');return}try{let fid=uid('requirement-file'),idb=await filesDB;await new Promise((res,rej)=>{let tx=idb.transaction('files','readwrite');tx.objectStore('files').put(file,fid);tx.oncomplete=res;tx.onerror=rej});l.files.push({id:fid,name:file.name,title:r.title,requirementId:r.id,release:'requirement',at:now()});r.fileIds=r.fileIds||[];r.fileIds.push(fid)}catch{toast('the sample file could not be saved');return}}else if(!r.fileIds?.length){toast('choose a test file, or indicate that you will provide it later');return}}r.status=r.kind==='text'||availability==='provide'?'submitted':availability==='missing'?'not available':'later';event(l,'requirement response: '+r.title+' / '+r.status);requirementStep++;if(requirementStep>=l.requirements.length){l.next='team checks the supplied information and confirms any missing requirements';save()}render();window.scrollTo(0,0)}
const beforeConversationClient=clientView;
clientView=function(){let l=lead(route[1]);if(l&&route[2]==='requirements'&&l.paid)return requirementsConversation(l);return beforeConversationClient()};
const previousAtomicActivation=simulateActivation;
simulateActivation=function(id){previousAtomicActivation(id);let l=lead(id);if(l?.paid){prepareRequirementJourney(l);requirementClient=l.id;requirementStep=0;render()}};
render();
